mapper.select:
select log_id, report_id, household_id, site_id, user_id, dong, ho, head_name, install_date, report_time, reporter_name, confirmer_name, confirmer_signature, photo_door, photo_before1, photo_after1, photo_before2, photo_after2, `status`, remarks, create_time, site_name, region_id, sido, sigungu, eupmyeondong, address, deleted_by, deleted_by_name, deleted_time, fix_reason, delete_reason from work_report_deletion_log
and region_id = #{regionId}
and sido = #{sido}
and sigungu = #{sigungu}
and deleted_time >= concat(#{startDate}, ' 00:00:00')
and deleted_time <= concat(#{endDate}, ' 23:59:59')
and ( site_name like concat('%', #{query}, '%') or dong like concat('%', #{query}, '%') or concat(dong, '동') like concat('%', #{query}, '%') or ho like concat('%', #{query}, '%') or concat(ho, '호') like concat('%', #{query}, '%') or head_name like concat('%', #{query}, '%') or reporter_name like concat('%', #{query}, '%') or deleted_by_name like concat('%', #{query}, '%') or delete_reason like concat('%', #{query}, '%') )
order by deleted_time desc limit #{limit} offset #{offset}

select count(*) from work_report_deletion_log
and region_id = #{regionId}
and sido = #{sido}
and sigungu = #{sigungu}
and deleted_time >= concat(#{startDate}, ' 00:00:00')
and deleted_time <= concat(#{endDate}, ' 23:59:59')
and ( site_name like concat('%', #{query}, '%') or dong like concat('%', #{query}, '%') or concat(dong, '동') like concat('%', #{query}, '%') or ho like concat('%', #{query}, '%') or concat(ho, '호') like concat('%', #{query}, '%') or head_name like concat('%', #{query}, '%') or reporter_name like concat('%', #{query}, '%') or deleted_by_name like concat('%', #{query}, '%') or delete_reason like concat('%', #{query}, '%') )
